  return value;
 };
 for (const key of ["AlchBubbles", "AlchVials", "BoxRewards", "FamBonusQTYs", "StarSigns", "CalcTalentMAP", "CardBonusS", "GalleryTrophyBonTOT", "GalleryNametagBonTOT", "PremHatBonTOT"]) {
