 if (!Number.isFinite(firstStoredPetPower)) throw new Error("Non-finite first stored pet power");
 return {powers, terms, bubbles, statues, ordinaryTalents, gear, context, sourceInputs: {firstStoredPetPower, cookingLevel: levels[10], gamingLevel: levels[15], sailingLevel: levels[13], divinityLevel: levels[14], intellectLevel: levels[12]}, cachedTotals: prepared.TotStatMAP.h};
})()
